#include <stdio.h>

typedef int (*transform)(int);

int double_it(int x) { return x * 2; }
int increment(int x) { return x + 1; }
int absolute(int x) { return x < 0 ? -x : x; }

int pipeline_run(int input, transform t[]) {
    for (int i = 0; t[i]; i++) input = t[i](input);
    return input;
}

int main() {
    transform pipeline[] = {absolute, double_it, increment, NULL};
    printf("Result: %d\n", pipeline_run(-3, pipeline));
    return 0;
}
